module old(input clk,input[7:0]a,b,output reg[15:0]y);reg[7:0]aq,bq;always@(posedge clk)begin aq<=a;bq<=b;y<=aq*bq;end endmodule
module candidate_rt(input clk,input[7:0]a,b,output reg[15:0]y);reg[7:0]p00,p10,p01,p11;always@(posedge clk)begin p00<=a[3:0]*b[3:0];p10<=a[7:4]*b[3:0];p01<=a[3:0]*b[7:4];p11<=a[7:4]*b[7:4];y<={8'd0,p00}+{4'd0,p10,4'd0}+{4'd0,p01,4'd0}+{p11,8'd0};end endmodule
module mutant(input clk,input[7:0]a,b,output reg[15:0]y);reg[7:0]aq,bq;always@(posedge clk)begin aq<=a;bq<=b;y<=a*b;end endmodule
module drop(input clk,input[7:0]a,b,output reg[15:0]y);reg[7:0]p00,p10,p01,p11;always@(posedge clk)begin p00<=a[3:0]*b[3:0];p10<=a[7:4]*b[3:0];p01<=0;p11<=a[7:4]*b[7:4];y<={8'd0,p00}+{4'd0,p10,4'd0}+{4'd0,p01,4'd0}+{p11,8'd0};end endmodule
module tb;reg clk=0;always#5 clk=~clk;reg[7:0]a,b;wire[15:0]g,c,m,d;old u0(clk,a,b,g);candidate_rt u1(clk,a,b,c);mutant u2(clk,a,b,m);drop u3(clk,a,b,d);integer i,j,bad=0,caught=0,dcaught=0,n=0;initial begin a=0;b=0;repeat(3)@(negedge clk);for(i=0;i<256;i=i+1)for(j=0;j<256;j=j+1)begin a=i;b=j;@(negedge clk);n=n+1;if(g!==c)bad=bad+1;if(g!==m)caught=caught+1;if(g!==d)dcaught=dcaught+1;end repeat(3)begin @(negedge clk);if(g!==c)bad=bad+1;end $display("MUL4_RT cycles%0d mismatch%0d wrongedge_mutant_caught%0d droppedpartial_caught%0d",n,bad,caught,dcaught);if(bad||!caught||!dcaught)$fatal;$finish;end endmodule
